			func('$menu', 'location_gray_tooltip', $menu_item_kulaconstruct_gray, empty, '증축 불가 (2000$)', '스파크가 부족하다')
		else
			func('$menu', 'interaction_city', $menu_item_kulaconstruct, menu_kulaconstruct2, '개인실을 2개로 늘린다 (2000$)')
		end
